accepted_solution:
def count_primes(numbers):
    def is_prime(n):
        if n < 2: return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0: return False
        return True
    return sum(1 for n in numbers if is_prime(n))

common_incorrect_submission:
def count_primes(numbers):
    # Treats 1 as prime
    return sum(1 for n in numbers if n > 0 and (n == 2 or n % 2 != 0))

